-- ========================================================
-- Database Full Schema & Seed: db_ttbp + st_master_toko
-- Compatible with MySQL 5.5+ / MariaDB 10.1+ (PHP 7.0+)
-- ========================================================

CREATE DATABASE IF NOT EXISTS `db_ttbp` DEFAULT CHARACTER SET utf8 COLLATE utf8_general_ci;
USE `db_ttbp`;

CREATE TABLE IF NOT EXISTS `roles` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `role_name` varchar(50) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;


CREATE TABLE IF NOT EXISTS `divisions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `division_name` varchar(100) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;


CREATE TABLE IF NOT EXISTS `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `role_id` int(11) NOT NULL DEFAULT 3,
  `division_id` int(11) NOT NULL DEFAULT 1,
  `name` varchar(100) NOT NULL,
  `username` varchar(50) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `last_login` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  UNIQUE KEY `email` (`email`),
  KEY `fk_users_roles` (`role_id`),
  KEY `fk_users_divisions` (`division_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;


CREATE TABLE IF NOT EXISTS `ttbp` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nomor_ttbp` varchar(50) NOT NULL,
  `tanggal` date NOT NULL,
  `kode_kios` varchar(50) DEFAULT NULL,
  `nama_kios` varchar(255) NOT NULL,
  `alamat` text DEFAULT NULL,
  `salesman` varchar(100) DEFAULT NULL,
  `realisasi_program` varchar(255) DEFAULT NULL,
  `id_program` int(11) DEFAULT NULL,
  `periode` varchar(100) DEFAULT NULL,
  `perhatian` text DEFAULT NULL,
  `disetujui_oleh` varchar(100) DEFAULT NULL,
  `dibuat_oleh` varchar(100) DEFAULT NULL,
  `penerima` varchar(100) DEFAULT NULL,
  `is_manual` tinyint(1) DEFAULT 0,
  `created_by` varchar(100) DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_nomor` (`nomor_ttbp`),
  KEY `idx_tanggal` (`tanggal`),
  KEY `idx_salesman` (`salesman`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;


CREATE TABLE IF NOT EXISTS `ttbp_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `ttbp_id` int(11) NOT NULL,
  `no_urut` int(11) NOT NULL DEFAULT 1,
  `nama_barang` varchar(255) NOT NULL,
  `jumlah` decimal(15,2) NOT NULL DEFAULT 1.00,
  `satuan` varchar(50) NOT NULL DEFAULT 'Unit',
  `keterangan` text DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ttbp` (`ttbp_id`),
  CONSTRAINT `fk_ttbp_items_ttbp` FOREIGN KEY (`ttbp_id`) REFERENCES `ttbp` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;


CREATE TABLE IF NOT EXISTS `laporan_bonus_promosi` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `no_urut_lap` varchar(50) DEFAULT NULL,
  `tanggal_ttbp` date DEFAULT NULL,
  `nomor_ttbp` varchar(50) DEFAULT NULL,
  `tgl_sdh_dipotong` date DEFAULT NULL,
  `faktur_promo` varchar(50) DEFAULT NULL,
  `kode_kios` varchar(50) DEFAULT NULL,
  `nama_pembeli` varchar(255) DEFAULT NULL,
  `alamat_manual` text DEFAULT NULL,
  `salesman_manual` varchar(100) DEFAULT NULL,
  `penerima_manual` varchar(100) DEFAULT NULL,
  `value_produk_program` decimal(15,2) DEFAULT 0.00,
  `program` varchar(255) DEFAULT NULL,
  `nama_barang` varchar(255) DEFAULT NULL,
  `potong_nota` decimal(15,2) DEFAULT 0.00,
  `pajak` decimal(15,2) DEFAULT 0.00,
  `total_bonus` decimal(15,2) DEFAULT 0.00,
  `qty` decimal(15,2) DEFAULT 0.00,
  `satuan` varchar(50) DEFAULT NULL,
  `volume_prog` decimal(15,2) DEFAULT 0.00,
  `satuan_vol` varchar(50) DEFAULT NULL,
  `periode_prog_awal` date DEFAULT NULL,
  `periode_prog_akhir` date DEFAULT NULL,
  `periode_prog_raw` varchar(100) DEFAULT NULL,
  `faktur` varchar(255) DEFAULT NULL,
  `kode_wilayah` varchar(50) DEFAULT NULL,
  `tgl_kembali_ttbp` date DEFAULT NULL,
  `dibuat_oleh` varchar(100) DEFAULT 'Nonik Dia',
  `disetujui_oleh` varchar(100) DEFAULT NULL,
  `perhatian` text DEFAULT NULL,
  `keterangan` text DEFAULT NULL,
  `ttbp_id` int(11) DEFAULT NULL,
  `status_ttbp` enum('pending','generated','returned') NOT NULL DEFAULT 'pending',
  `periode_laporan` varchar(100) DEFAULT 'Januari - Desember 2026',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `nomor_ttbp` (`nomor_ttbp`),
  KEY `kode_kios` (`kode_kios`),
  KEY `status_ttbp` (`status_ttbp`),
  KEY `ttbp_id` (`ttbp_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1023 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;


CREATE TABLE IF NOT EXISTS `st_master_toko` (
  `kode_toko` varchar(50) NOT NULL,
  `nama_toko` varchar(255) DEFAULT NULL,
  `kota` varchar(100) DEFAULT NULL,
  `alamat` text DEFAULT NULL,
  `se` varchar(100) DEFAULT NULL,
  `sc` varchar(100) DEFAULT NULL,
  `kontak_person` varchar(100) DEFAULT NULL,
  `telepon_1` varchar(50) DEFAULT NULL,
  `telepon_2` varchar(50) DEFAULT NULL,
  `telepon_3` varchar(50) DEFAULT NULL,
  `telepon_4` varchar(50) DEFAULT NULL,
  `telepon` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`kode_toko`),
  KEY `idx_se` (`se`),
  KEY `idx_sc` (`sc`),
  KEY `idx_nama_toko` (`nama_toko`(50))
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;


